contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, uint minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount > 0);
        require(minSum <= amount);

        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(reverted || afterBal == beforeBal - amount);
    }

    receive() external payable {}
}

